sheet({title:'Stinger', units:'in'})

// Robots must fit inside the 18 x 18 x 18 box at the start of the match
box(-9,-9,0,  18,18,18,  {fill:C.white, alpha:0.15, limit:true})


// ---------- Variables ----------
const W  = 17,   L  = 17.5           // frame outside width (x) and length (y)
const T  = 2.76, H  = 4.5,  Z0 = 1   // rail thickness, rail height, bottom of the rails above the tiles
const th = 16 * Math.PI / 180        // ramp angle, radians
const RY = -8.25, RZ = 4.8, RF = 2.5 // roller: axle y, axle z, how far the tubing sticks out past the core
const SX = 0, SY = 0.6, SZ = 2.28    // spindexer centre x,y and the plate's underside (sits on the cross member)
const SR = 4.92, PR = 2.94, CR = 1.18 // plate radius, pocket radius, cup radius
const P  = 4                         // seconds between balls; also the time between spindexer steps
const TZ = 8.5                       // height the lift carries a ball to (turret inlet; placeholder until the turret exists)


// ---------- Game pieces (not part of the robot: the size limit ignores them) ----------
const balls  = [pollen(0,-11), nectar(0,-15), pollen(0,-19), nectar(0,-23)]   // max 4 on board
const radii  = [1.40, 1.81, 1.40, 1.81]
const starts = [-11, -15, -19, -23]


// ---------- Chassis ----------
// Frame rails
for (const x of [-8.06, 5.11]) {
  box(x, -L/2, 0,  T, L, H,  {fill:C.alu})            // rails start at the front edge
}
dim([-8.06, -L/2, H], [-8.06, L/2, H],  {off:40, text:`${L}" chassis length`})
dim([-8.06, -L/2, H], [-5.30, -L/2, H], {off:40, text:`${T}" rail width`})

// Cross members (hold the two rails together)
for (const y of [-0.945, 6]) {
  box(-5.3, y, 1.81,  10.39, 1.89, 0.47,  {fill:C.alu})
}
dim([-5.3, 6, 2.28], [5.09, 6, 2.28], {off:40})                       // 10.39
leader([0, 6, 2.28], 'cross member 1.89 × 0.47, 2×', 60, -50)

// Wheels: 104 mm mecanum
for (const x of [-7.43, 5.74]) {     // 0.63 in from each rail's left face
  for (const y of [-6.61, 6.61]) {   // tread ends flush with the rail ends
    cyl(x, y, 2.05,  2.05, 1.5,  {axis:'x', fill:C.dark})
  }
}
dim([-7.43, -6.61, 0],    [-7.43, -6.61, 4.1],  {off:-40})            // diameter 4.10
dim([-7.43, -6.61, 2.05], [-5.93, -6.61, 2.05], {off:40})             // width 1.50
leader([-7.43, -6.61, 4.1], '104 mm mecanum, 4×', -60, -40)


// ---------- Intake ----------
// Ramp
let fl = box(-5.3, -L/2, 0.3,  10.40, 7.04, 0.125,  {fill:C.blue})
fl.rot[0] = 16
dim([-5.3, -L/2, 0.3], [5.1, -L/2, 0.3], {off:50})
leader([0, -5, 1.2], '16° ramp', 60, -40)

// Guides (ride on the ramp)
let gl = box(-5.0,  -L/2+0.4, 0.425,  0.125, 6, 1.5,  {fill:C.alu, part:fl})
let gr = box(4.875, -L/2+0.4, 0.425,  0.125, 6, 1.5,  {fill:C.alu, part:fl})
gl.rot[2] = -25
gr.rot[2] =  25
dim([-2.35, -3.5, 1.8], [2.34, -3.5, 1.8], {off:-40})                 // throat ≈ 4.69

// Roller: core ahead of the lip, raised so the balls pass underneath
let rl = cyl(-4, RY, RZ,  0.75, 8,  {axis:'x', fill:C.dark})          // roller core
for (let i = 0; i < 12; i++) {
  const x = -3.5 + i*0.65                                            // a finger every 0.65 in along the core
  const f = cyl(x, RY, RZ,  0.12, 0.75+RF,  {axis:'z', fill:C.yellow, part:rl, pivot:[x, RY, RZ]})
  f.rot[0] = (i % 2) * 180                                           // two rows, 180° apart
}
dim([-4, RY, 0], [-4, RY, RZ-0.75], {off:-60})                        // clearance under the core
leader([-4, RY, RZ+0.75+RF], 'tubing fingers, parked vertical at start', -60, -40)


// ---------- Spindexer ----------
let sp = part({pivot:[SX, SY, SZ]})                                   // the hub everything turns about
cyl(SX, SY, SZ,  SR, 0.25,  {axis:'z', fill:C.blue, part:sp})         // Ø9.85 plate
cyl(SX, SY, SZ+0.25,  0.6, 2.2,  {axis:'z', fill:C.alu, part:sp})     // centre post

for (let i = 0; i < 4; i++) {
  // pockets at 270° (front, fed by the ramp), 0° (right), 90° (back = transfer station), 180° (left)
  const a = (270 + i*90) * Math.PI/180
  cyl(SX + PR*Math.cos(a), SY + PR*Math.sin(a), SZ+0.2,  CR, 0.06,  {axis:'z', fill:C.dark, part:sp})   // cup ring
  // fins between the pockets: from r=1.6 out to the rim, 1.4 tall
  const fin = box(SX+1.6, SY-0.08, SZ+0.25,  SR-1.9, 0.16, 1.4,  {fill:C.alu, part:sp, pivot:[SX, SY, SZ]})
  fin.rot[2] = 45 + i*90
}
dim([SX-SR, SY, SZ], [SX+SR, SY, SZ], {off:70, text:'Ø9.85 spindexer'})
dim([SX, SY, SZ+0.25], [SX, SY-PR, SZ+0.25], {off:-40, text:'R2.94 pockets'})


// ---------- Motion ----------
// Spindexer: step k happens when ball k has settled in the front pocket (3.8 s into its story)
function index(t, period, move) {
  const k = Math.floor(t / period)                 // steps completed
  const f = Math.min(1, (t - k*period) / move)     // progress through the current step, 0→1
  const e = f*f*(3 - 2*f)                          // ease: slow start, slow stop
  return 90 * (k + e)
}

// One ball's whole story. tb = its own clock (negative = waiting); k = which ball it is (0..3)
function journey(ball, r, y0, tb, k) {
  let x = 0, y, z
  const cupZ = SZ + 0.25 + 0.5 + r - 0.35                      // centre height when sitting in a cup
  if (tb < 0)        { y = y0; z = r }                                                                   // waiting on the tiles
  else if (tb < 1.5) { y = y0 + tb/1.5 * (-8.75 - y0); z = r }                                           // dragged to the lip
  else if (tb < 3.5) { y = -8.75 + (tb-1.5)/2 * 6;  z = 0.425 + (y+8.75)*Math.tan(th) + r/Math.cos(th) } // up the ramp
  else if (tb < 3.8) { const f = (tb-3.5)/0.3; y = -2.75 + f*(SY-PR+2.75); z = 2.3 + f*(cupZ-2.3) }      // into the front pocket
  else {
    // riding in its pocket: it landed at 270° (front) after k steps had already happened
    const ang = (270 + sp.rot[2] - 90*k) * Math.PI/180
    x = SX + PR*Math.cos(ang);  y = SY + PR*Math.sin(ang);  z = cupZ
    const tStation = 3.8 + 2*P + 0.6                                                 // two steps later: at the back
    if (tb > tStation)       z = cupZ + Math.min(1, (tb-tStation)/1.0) * (TZ - cupZ) // lift carries it up to the turret
    if (tb > tStation + 1.6) { x = 0; y = y0; z = r }                                // shot (placeholder): back to the tiles
  }
  ball.pos = [x, y - y0, z - r]
}

animate(t => {
  rl.rot[0] = t * 360                          // roller, 1 turn/s (fingers built vertical = parked at t=0)
  sp.rot[2] = index(t - 3.8, P, 0.6)           // first step 0.3 s after ball 0 lands; then every P seconds
  const tc = t % (4*P + 14)                    // one 4-ball cycle, then repeat
  for (let k = 0; k < 4; k++) journey(balls[k], radii[k], starts[k], tc - k*P, k)
})
